def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = 0
    my_c = 0
    for me, op in history:
        if me == 'C':
            my_c += 1
        if op == 'C':
            opp_c += 1

    opp_rate = opp_c / float(n)

    rec = 8 if n >= 8 else n
    recent_opp_c = 0
    for i in range(n - rec, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / float(rec)

    after_my_c_c = 0
    after_my_c_d = 0
    after_my_d_c = 0
    after_my_d_d = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        op = history[i][1]
        if prev_my == 'C':
            if op == 'C':
                after_my_c_c += 1
            else:
                after_my_c_d += 1
        else:
            if op == 'C':
                after_my_d_c += 1
            else:
                after_my_d_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    recent_my_d = 0
    start = n - 3
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    if opp_c == 0:
        return 'D'

    if opp_rate <= 0.32 or recent_rate <= 0.12:
        if last_opp == 'C' and after_my_c_c >= after_my_c_d + 2 and recent_rate >= 0.25:
            return 'C'
        return 'D'

    nonretaliator = (
        after_my_d_c >= 1 and
        after_my_d_d == 0 and
        opp_rate >= 0.84 and
        recent_rate >= 0.60
    )

    if opp_rate >= 0.70:
        if last_opp == 'D':
            if opp_d_streak >= 3 and recent_my_d == 0:
                return 'D'

            if recent_my_d > 0:
                if opp_d_streak >= 4:
                    return 'D'
                return 'C'

            if opp_d_streak >= 2:
                return 'D'

            if rng.random() < 0.12 and opp_rate >= 0.90:
                return 'C'
            return 'D'

        if nonretaliator:
            return 'D'

        if recent_my_d > 0:
            return 'C'

        return 'C'

    if last_opp == 'D':
        if recent_my_d > 0:
            if opp_d_streak >= 3:
                return 'D'
            return 'C' if rng.random() < 0.55 else 'D'

        if opp_d_streak >= 2:
            return 'D'

        if rng.random() < 0.18 and recent_rate >= 0.45:
            return 'C'

        return 'D'

    if nonretaliator and recent_rate >= 0.50:
        return 'D'

    if recent_my_d > 0 and recent_rate >= 0.55:
        return 'C'

    return 'C'
